   ): () => void {
     let _unreg: (() => void) | undefined;
     let _function: ((...arguments_: any) => any) | undefined = (
       ...arguments_: any
     ) => {
       if (typeof _unreg === "function") {
         _unreg();
       }
       _unreg = undefined;
       _function = undefined;
